<template>
  <section class="role-section">
    <header><p class="eyebrow">Practitioner</p><h2>My appointment calendar</h2><p>Appointments assigned to you across the selected month.</p></header>
    <div class="metric-grid"><article v-for="metric in metrics" :key="metric.label" class="metric"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small>{{ metric.note }}</small></article></div>
    <div class="panel-grid"><article class="panel"><div class="calendar-heading"><button type="button" @click="shiftMonth(-1)">Previous</button><h3>{{ monthLabel }}</h3><button type="button" @click="shiftMonth(1)">Next</button></div><div class="calendar"><span v-for="day in weekdays" :key="day" class="weekday">{{ day }}</span><button v-for="cell in calendarCells" :key="cell.key" type="button" class="day" :class="{ muted: !cell.inMonth, selected: selectedDate === cell.key, booked: cell.count }" :disabled="!cell.inMonth" @click="selectedDate = cell.key"><b>{{ cell.day }}</b><small v-if="cell.count">{{ cell.count }} appt{{ cell.count === 1 ? '' : 's' }}</small></button></div></article><article class="panel"><h3>{{ selectedLabel }}</h3><div v-if="selectedAppointments.length" class="appointment-list"><article v-for="item in selectedAppointments" :key="item.id"><b>{{ formatTime(item.time) }} · {{ item.clientName || item.patientName || 'Client' }}</b><span>{{ item.service || 'Service not specified' }}</span><small>{{ item.status || 'Scheduled' }}</small></article></div><p v-else class="empty">No assigned appointments for this day.</p></article></div>
  </section>
</template>
<script setup>
import { computed, ref } from 'vue'
import { formatClockTime } from '@/utils/appointmentDss'
const props = defineProps({ appointments: { type: Array, default: () => [] }, userId: { type: String, default: '' } })
const weekdays = ['S', 'M', 'T', 'W', 'T', 'F', 'S']
const month = ref(new Date())
const dateKey = date => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
const assigned = computed(() => props.appointments.filter(item => [item.practitionerId, item.assignedPractitionerId, item.staffId, item.assignedTo].some(value => String(value || '') === props.userId)))
const selectedDate = ref(dateKey(new Date()))
const monthLabel = computed(() => month.value.toLocaleDateString(undefined, { month: 'long', year: 'numeric' }))
const selectedLabel = computed(() => new Date(`${selectedDate.value}T12:00:00`).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' }))
const calendarCells = computed(() => { const first = new Date(month.value.getFullYear(), month.value.getMonth(), 1); const start = new Date(month.value.getFullYear(), month.value.getMonth(), 1 - first.getDay()); return Array.from({ length: 42 }, (_, index) => { const date = new Date(start); date.setDate(start.getDate() + index); const key = dateKey(date); return { key, day: date.getDate(), inMonth: date.getMonth() === month.value.getMonth(), count: assigned.value.filter(item => item.date === key).length } }) })
const selectedAppointments = computed(() => assigned.value.filter(item => item.date === selectedDate.value).sort((a, b) => String(a.time || '').localeCompare(String(b.time || ''))))
const today = dateKey(new Date())
const metrics = computed(() => [{ label: 'Today', value: assigned.value.filter(item => item.date === today).length, note: 'Appointments assigned to you' }, { label: 'This month', value: assigned.value.filter(item => String(item.date || '').startsWith(dateKey(month.value).slice(0, 7))).length, note: monthLabel.value }, { label: 'Selected day', value: selectedAppointments.value.length, note: selectedLabel.value }])
const shiftMonth = offset => { const next = new Date(month.value); next.setMonth(next.getMonth() + offset); month.value = next }
const formatTime = value => formatClockTime(value) || 'Time TBD'
</script>
<style scoped>
.role-section{display:grid;gap:1rem;color:#4a3324}.role-section header h2{margin:.25rem 0;font:600 1.65rem Georgia,serif;color:#402719}.role-section header p:last-child{margin:.3rem 0;color:#806b5a}.eyebrow{margin:0;color:#91643f;font-size:.68rem;font-weight:700;letter-spacing:.18em;text-transform:uppercase}.metric-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:.8rem}.metric,.panel{min-width:0;border:1px solid #ead8c2;border-radius:1rem;background:#fffdf9;padding:1rem;box-shadow:0 8px 24px #4b311e0a}.metric span,.metric small{display:block;color:#806b5a;font-size:.8rem}.metric strong{display:block;margin:.45rem 0;color:#4a2d1c;font-size:1.7rem}.panel-grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(250px,.8fr);gap:1rem}.panel h3{margin:0;color:#4a2d1c;font-size:1rem}.calendar-heading{display:flex;justify-content:space-between;align-items:center;gap:.5rem;margin-bottom:.8rem}.calendar-heading button{border:1px solid #e6d2bc;border-radius:.6rem;background:#fffaf4;padding:.5rem .7rem;color:#674a36;font-size:.8rem}.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:.25rem}.weekday{text-align:center;color:#806b5a;font-size:.68rem;font-weight:700}.day{display:flex;min-height:58px;flex-direction:column;justify-content:space-between;border:1px solid #efe3d5;border-radius:.5rem;background:#fffdfa;padding:.35rem;text-align:left;color:#513722}.day.booked{background:#f8efe5;border-color:#c49b79}.day.selected{outline:2px solid #987052;outline-offset:1px}.day small{color:#91643f;font-size:.6rem}.day.muted{opacity:.4}.appointment-list{display:grid;gap:.55rem;margin-top:.8rem}.appointment-list article{display:grid;gap:.25rem;border:1px solid #efe3d5;border-radius:.7rem;padding:.7rem;background:#fffaf4}.appointment-list b{font-size:.82rem;color:#4a2d1c}.appointment-list span,.appointment-list small,.empty{color:#806b5a;font-size:.78rem}.empty{margin-top:.8rem}@media(max-width:800px){.panel-grid{grid-template-columns:1fr}}@media(max-width:600px){.role-section header h2{font-size:1.4rem}.day{min-height:45px;padding:.25rem}.day small{font-size:.54rem}}
</style>
